import sys,json,time,shutil
import numpy as np
from scipy import sparse
from scipy.optimize import lsq_linear
from baseline_registry import ROOT,REPO,ref,dump,sha

def main():
 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());c=np.load(REPO/s['output']['path']);P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);q=p['q'];lo=p['lower'];hi=p['upper'];eq=np.isfinite(hi)&(lo==hi);ineq=~eq;x=c['before_x'];dx=c['direction'];new=c['after_x'];V=c['V'];B=np.asarray(A@V);sl=A@x-lo;f=V.T@(P@x+q);y=c['LP_dual'];lz=c['coefficients'];lpgrad=f+B.T@y;lpsl=sl+B@lz;gt=float((P@x+q)@dx);curv=float(dx@(P@dx));alpha=min(1.,-gt/curv) if gt<0 and curv>0 else 1.;prop=x+alpha*dx;end=A@prop-lo;pr=max(float(np.max(np.maximum(-end[ineq],0))),float(np.max(abs(end[eq]))));obj=lambda z:float(.5*z@(P@z)+q@z);accepted=pr<1e-10 and gt<0 and obj(prop)<=obj(x)+1e-4*alpha*gt;newnear=np.flatnonzero(ineq&(end<=1e-10)&(sl>1e-10));ns=json.loads((REPO/s['source']['path']).read_text());nd=np.load(REPO/ns['output']['path']);pv=P@V;oldact=nd['active'];nullwork=V.T@(P@x+q);over=A@(x+2*dx)-lo;overpr=float(np.max(np.maximum(-over[ineq],0)));wrong=float(np.max(abs(f-B.T@y)));m=s['metrics'];checks=dict(output_hash=sha(REPO/s['output']['path'])==s['output']['SHA256'],all_original_rows=A.shape==(2208,72231),all_finite_gap_rows_reproduced=np.max(abs(B-c['B']))<1e-12,all_original_RHS_reproduced=np.max(abs(sl-c['full_gap_RHS']))<1e-12,original_objective_f=np.max(abs(f-c['objective_f']))<1e-12,affine_work_nonzero=np.min(abs(nullwork))>1e-8,physical_null_action_measured=np.max(abs(pv-c['physical_Pv']))<1e-12,active_null_motion=np.max(abs(B[oldact]))<1e-10,all_coordinates_reproduced=np.max(abs(dx-V@lz))<1e-12,LP_stationarity=np.max(abs(lpgrad))<1e-8,LP_sign=np.max(np.maximum(y[ineq],0))<1e-8,LP_complementarity=np.max(abs(lpsl[ineq]*y[ineq]))<1e-8,allrow_primal=pr<1e-10,original_P_curvature=abs(curv-m['physical_curvature_Nmm'])<1e-15,objective_decreases=obj(prop)<obj(x),acceptance_reproduced=accepted==bool(s['accepted_linear_steps']),accepted_state_reproduced=np.max(abs(new-(prop if accepted else x)))<1e-12,new_blocking_rows=np.array_equal(newnear,m['new_near_original_rows']),original_affine_sign_control=wrong>1e-8,ignore_finite_blockers_control=overpr>1e-10,no_support_update=s['actual_support_updates']==0)
 # Search duals are not equilibrium pressures: independently recover physical cone.
 ss=A@new-lo;active=np.union1d(np.flatnonzero(eq),np.flatnonzero(ineq&(abs(ss)<1e-10)));Ar=A[active].T.toarray();force=P@new+q;r=lsq_linear(Ar,-force,bounds=(np.full(len(active),-np.inf),np.where(ineq[active],0.,np.inf)),method='bvls',tol=1e-13,max_iter=200,lsq_solver='exact');yy=np.zeros(len(lo));yy[active]=r.x;res=force+A.T@yy;physical=dict(primal_mm=max(float(np.max(np.maximum(-ss[ineq],0))),float(np.max(abs(ss[eq])))),stationarity_N=float(np.max(abs(res))),sign_N=float(np.max(np.maximum(yy[ineq],0))),complementarity_Nmm=float(np.max(abs(ss[ineq]*yy[ineq]))),gauge_N=float(np.max(abs(yy[eq]))),RootY_gamma_stationarity_N=float(abs(yy[2175])));physical['qualified']=all(v<1e-8 for v in physical.values());np.savez_compressed(out/'physical_recovery.npz',x=new,y=yy,residual=res,slack=ss,active=active);physical['output']=ref(out/'physical_recovery.npz');checks['search_not_promoted_to_equilibrium']=not physical['qualified'];ok=all(checks.values());result=dict(status='ACTUAL_P1_FINITE_NULL_STEP_INDEPENDENT_AUDIT_PASS' if ok else 'ACTUAL_P1_FINITE_NULL_STEP_INDEPENDENT_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),verifier=ref(out/'verifier.py'),checks={k:bool(v) for k,v in checks.items()},metrics=dict(physical_objective_before_Nmm=obj(x),physical_objective_after_Nmm=obj(new),physical_directional_objective_Nmm=gt,physical_curvature_Nmm=curv,allrow_primal_mm=pr,LP_stationarity=float(np.max(abs(lpgrad))),LP_complementarity_Nmm=float(np.max(abs(lpsl[ineq]*y[ineq]))),new_original_rows=newnear.tolist(),original_null_action_max_N=float(np.max(abs(pv))),null_affine_work_Nmm=nullwork.tolist(),wrong_affine_sign_defect=wrong,double_step_ignored_blocker_primal_mm=overpr),independent_physical_KKT=physical,actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-t,limitations=['Actual null LP/linear-step audit with full physical KKT rejection, not coupled nonlinear or system qualification.','Null diagnostic immutable field external_affine_work_Nmm means residual affine work v dot(Px+q), not external load alone; working label corrected without altering original evidence.']);dump(out/'summary.json',result);print(json.dumps(result));raise SystemExit(0 if ok else 2)
